-- Complete elective and specialty lab lists from the SPPU SE/TE/BE syllabi.
-- Update only syllabus titles; faculty-set dates, notes, and audit fields are preserved.
with syllabus(academic_year, semester, course_code, lab_course, subject_name, elective_name, titles) as (
 values
(3,5,'PEC-322','Elective I Lab','Advanced Java Programming','Elective I',ARRAY['Store student records in an ArrayList and implement insert, delete, search, update, and iteration','Use Set to remove duplicates and sort data; use PriorityQueue for task processing','Store student records in HashMap and sort with Comparable and Comparator','Build a Swing GUI to enter subject marks and display a result window','Create a Swing frame and handle mouse-click, mouse-enter, and mouse-exit events','Build a JavaFX form with text input, button events, and property binding','Create a JSP employee-information application using implicit objects and Expression Language','Build a calculator application using a servlet','Create a Java web login form using cookies and HttpSession','Use JDBC to insert, update, delete, and display student records','Execute HQL queries for data retrieval','Build an annotation-based student-management system','Create a Spring Boot application that displays a welcome message','Create and test a student-information REST API using Spring Boot','Build a Spring Boot application that accepts student details and returns JSON','Compulsory mini-project' ]::text[]),
(3,6,'PEC-363','Elective II Lab','Network & Cyber Security','Elective II',ARRAY['Implement substitution/transposition encryption and decryption','Implement steganography and analyze its security properties','Analyze and prevent SQL injection','Monitor network threats and analyze packets using Wireshark','Evaluate password strength and cracking resistance with John the Ripper','Analyze TCP handshake, DNS, ARP, HTTP/HTTPS, and fragmentation in Wireshark','Perform active reconnaissance, vulnerability identification, and port scanning using Nmap','Implement RSA or Diffie-Hellman asymmetric cryptography','Case study: solve cybersecurity challenges using CyLab Security Academy','Project: cyber ethics and data privacy risk assessment' ]::text[]),
(3,6,'PEC-363','Elective II Lab','CMOS Process Technology','Elective II',ARRAY['Simulate CMOS inverter characteristics using SPICE or an equivalent tool','Simulate CMOS NAND and NOR gates','Simulate a CMOS 2:1 multiplexer','Simulate a transmission-gate 2:1 multiplexer','Design a CMOS inverter layout','Design NAND and NOR layouts','Design a CMOS half-adder layout','Design a CMOS full-adder layout','Design a 2:1 multiplexer layout using CMOS and transmission gates','Project: student-selected CMOS design implementation','Study CMOS process scaling from 180 nm to 5 nm','Study FinFET technology from planar to 3D transistors' ]::text[]),
(3,6,'PEC-363','Elective III Lab','Power Electronics','Elective III',ARRAY['Measure SCR V-I and gate characteristics and compare with datasheet specifications','Measure power MOSFET output/transfer characteristics and threshold voltage','Measure IGBT output/transfer characteristics and threshold voltage','Implement a single-phase AC voltage controller with R/RL loads','Build a single-phase PWM MOSFET/IGBT bridge inverter and measure output','Implement a step-up/step-down chopper and measure duty-cycle effects','Evaluate SMPS/UPS load and line regulation','Simulate a single-phase AC voltage controller using PowerSim or equivalent','Study speed control of a DC or single-phase AC motor','Case study: solar-cell emergency lighting system','Case study: electric vehicle' ]::text[]),
(3,6,'PEC-363','Elective III Lab','Robotics & Automation','Elective III',ARRAY['Calibrate an industrial load-cell strain gauge and evaluate static characteristics','Control a servo motor for a single-link robotic arm','Build a line-following mobile robot using IR sensors and DC motors','Build a PLC-based automatic water-level controller','Automate a traffic signal using PLC timers, counters, and sequence logic','Design an automated conveyor-belt control system','Implement forward kinematics of a two-link planar robotic arm','Design a pick-and-place robotic manipulator','Implement an automated conveyor using sensors and sequential control','Build a line-following robot using IR sensors and differential drive','Case study: pick-and-place robot in manufacturing','Case study: automated conveyor system in packaging' ]::text[]),
(3,6,'PEC-363','Elective III Lab','Artificial Intelligence','Elective III',ARRAY['Build a Python expert system for a constraint-satisfaction problem','Solve map coloring, Sudoku, or timetable scheduling using backtracking','Solve the 8-puzzle using depth-first or breadth-first search','Implement greedy best-first search for a map problem','Implement the A* algorithm for a search problem','Implement Minimax for game playing','Parse a family tree using a knowledge base','Implement forward chaining or backward chaining','Solve the 8-Queens problem using a basic search strategy','Build Tic-Tac-Toe using Minimax','Build a chatbot for a real-world scenario','Case study: responsible use of generative AI tools','Case study: image generation or prompt engineering','Open-ended assignment using agentic or generative AI' ]::text[]),
(3,6,'PEC-363','Elective III Lab','Industrial IoT','Elective III',ARRAY['Control stepper-motor acceleration, position, and speed with a dedicated driver','Use a stepper motor and proximity sensor to index a conveyor/table','Build a sensor-based smart-home automation model in Tinkercad','Compare industrial communication protocols for bandwidth, power, latency, range, and reliability','Build an MQTT system that publishes and subscribes to industrial sensor data','Analyze and visualize industrial sensor data from CSV using statistics and plots','Project: design an industrial communication and control testbed for a smart microgrid','Project: design an industrial case study using IIRA architecture and distributed data' ]::text[]),
(3,6,'MDM-371','Database Management System Lab','Database Management System',null,ARRAY['Prepare an ER diagram for an RDBMS case study','Create and modify tables using SQL DDL statements','Insert, select, update, and delete records using SQL DML','Perform SQL inner, left, right, cross, self, and natural joins','Write multi-table queries with joins, aggregates, GROUP BY, and HAVING','Create a SQL function to calculate salary, grade, or fine','Retrieve records using an explicit cursor and cursor attributes','Create a trigger to update an audit, stock, or salary table','Implement MongoDB CRUD operations and logical operators','Use MongoDB aggregation and indexing','Implement MongoDB MapReduce' ]::text[]),
(4,8,'404195','Fiber Optic Lab','Fiber Optic Communication',null,ARRAY['Estimate the numerical aperture of a multimode step-index optical fiber','Plot electrical and optical characteristics of an LED or laser source','Measure optical-fiber attenuation coefficient and bending losses','Plot characteristics of a photodetector','Complete a tutorial on numerical and key optical-fiber/source/detector components','Establish a digital optical link','Simulate optical power-budget and rise-time-budget analyses','Study an optical field instrument such as a power meter, OTDR, or splicing machine','Complete an optical-link-budget tutorial and assess system viability','Simulate a WDM system and compute OSNR','Study current trends in optical communication components, instruments, and standards' ]::text[])
), numbered as (
 select academic_year, semester, course_code, lab_course, subject_name, elective_name,
        title, ordinality::smallint as experiment_number
 from syllabus cross join lateral unnest(titles) with ordinality as item(title, ordinality)
)
insert into public.labmate_experiments
 (academic_year, semester, course_code, lab_course, subject_name, elective_name, experiment_number, title)
select academic_year, semester, course_code, lab_course, subject_name, elective_name, experiment_number, title
from numbered
on conflict (academic_year, semester, course_code, subject_name, experiment_number)
do update set
  lab_course = excluded.lab_course,
  elective_name = excluded.elective_name,
  title = excluded.title;
